 @Test void transientRetryIsBoundedAndUsesSameBusinessKey(){long id=delivery(submit(message("EMAIL")));var retryJobs=new CommunicationJobs(f.db,s,(c,k,u,t,body)->new CommunicationSender.Result("FAILED","TEMPORARY",null,true));var at=CommunicationService.now();f.run(()->retryJobs.deliver(at));f.run(()->retryJobs.deliver(at.plusMinutes(2)));f.run(()->retryJobs.deliver(at.plusMinutes(8)));f.run(()->retryJobs.deliver(at.plusDays(1)));assertThat(count("communication_attempts","delivery_id="+id)).isEqualTo(3);assertThat(count("communication_deliveries","id="+id)).isOne();assertThatThrownBy(()->f.run(()->s.retry(f.owner,id))).isInstanceOf(RuntimeException.class);}
 @Test void unknownProviderOutcomeIsNotAutomaticallyRetried(){long id=delivery(submit(message("EMAIL")));var unknown=new CommunicationJobs(f.db,s,(c,k,u,t,body)->new CommunicationSender.Result("UNKNOWN","TIMEOUT",null,false));f.run(()->unknown.deliver(CommunicationService.now()));f.run(()->unknown.deliver(CommunicationService.now().plusDays(1)));assertThat(state(id)).isEqualTo("UNKNOWN");assertThat(count("communication_attempts","delivery_id="+id)).isOne();}
